parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
const msg = $json.message || {};
const chatId = msg.chat?.id;
const messageId = msg.message_id;
const nombreContacto = [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.from?.username || '';

let fileId = null, mimeType = null, tipoMensaje = 'document', caption = msg.caption || '';
if (msg.photo && msg.photo.length) {
  const best = msg.photo[msg.photo.length - 1];
  fileId = best.file_id;
  mimeType = 'image/jpeg';
  tipoMensaje = 'image';
} else if (msg.voice) {
  fileId = msg.voice.file_id;
  mimeType = msg.voice.mime_type || 'audio/ogg';
  tipoMensaje = 'audio';
} else if (msg.audio) {
  fileId = msg.audio.file_id;
  mimeType = msg.audio.mime_type || 'audio/mpeg';
  tipoMensaje = 'audio';
} else if (msg.document) {
  fileId = msg.document.file_id;
  mimeType = msg.document.mime_type || 'application/octet-stream';
  tipoMensaje = mimeType === 'application/pdf' ? 'pdf' : 'document';
}

if (!chatId || !fileId) {
  return [{ json: { skip: true, skipReason: 'sin_chat_id_o_file_id' } }];
}

if (!staticData.seenTgMessageIds) staticData.seenTgMessageIds = {};
const now = Date.now();
Object.keys(staticData.seenTgMessageIds).forEach(id => {
  if (now - staticData.seenTgMessageIds[id] > 60000) delete staticData.seenTgMessageIds[id];
});
const dedupeKey = `${chatId}_${messageId}`;
if (staticData.seenTgMessageIds[dedupeKey]) {
  return [{ json: { skip: true, skipReason: 'duplicate_messageId' } }];
}
staticData.seenTgMessageIds[dedupeKey] = now;

return [{ json: {
  telefono: 'tg_' + chatId,
  chatId, fileId, mimeType, tipoMensaje, caption, nombreContacto, messageId, skip: false
} }];

const ext = $json;
return [{ json: {
  media_id: ext.fileId,
  mime_type: ext.mimeType,
  caption: ext.caption,
  platform: 'telegram',
  phone_number_id: '',
  gemini_api_key: ''
} }];

const resultado = $input.first().json;
const ext = $('🔧 Extraer Datos de Medio (TG)').first().json;
const tipo = ext.tipoMensaje || 'archivo';
const etiquetas = { image: 'imagen', audio: 'audio', document: 'documento', pdf: 'documento', video: 'video' };
const prefijo = `[Cliente envió ${etiquetas[tipo] || 'un archivo'}] `;
const textoProcesado = (resultado && !resultado.error && resultado.texto) ? resultado.texto : '[No se pudo procesar el archivo enviado]';

return [{ json: {
  telefono: ext.telefono,
  chatId: ext.chatId,
  texto: prefijo + textoProcesado,
  messageId: ext.messageId,
  nombreContacto: ext.nombreContacto,
  tipoMensaje: ext.tipoMensaje,
  skip: false
} }];

// Guardia anti-race: G54 tiene su propio webhook de Telegram (usado por el panel "Configurar bot")
// y n8n también se registra directo — Telegram solo permite UNO a la vez, gana el último que se registró.
// Este chequeo confirma que el webhook real siga apuntando a n8n y lo re-registra solo si alguien
// (ej. G54) lo pisó, sin esperar a que alguien note que Marco dejó de responder.
const BOT_TOKEN = "8821887883:AAGdWLtXtfaGDq3vSTrvd2p-zlu3NilK6CE";
const EXPECTED_URL = "https://n8n.mdarthurdigital.com/webhook/2866d067-d9d4-498e-976c-ec09b6d214f9/webhook";

const resp = await this.helpers.httpRequest({
  method: "GET",
  url: `https://api.telegram.org/bot${BOT_TOKEN}/getWebhookInfo`,
  json: true
});

const currentUrl = resp?.result?.url || "";
const correcto = currentUrl === EXPECTED_URL;

return [{ json: { correcto, currentUrl, expectedUrl: EXPECTED_URL } }];

const BOT_TOKEN = "8821887883:AAGdWLtXtfaGDq3vSTrvd2p-zlu3NilK6CE";
const EXPECTED_URL = "https://n8n.mdarthurdigital.com/webhook/2866d067-d9d4-498e-976c-ec09b6d214f9/webhook";

const resp = await this.helpers.httpRequest({
  method: "GET",
  url: `https://api.telegram.org/bot${BOT_TOKEN}/setWebhook?url=${encodeURIComponent(EXPECTED_URL)}&allowed_updates=%5B%22message%22%5D`,
  json: true
});

return [{ json: { ...$json, reRegistrado: true, resultado: resp } }];

const staticData = $getWorkflowStaticData('global');
const body = $json.body || $json;
const chatId = body.chat_id;
const texto = (body.texto || '').trim();
const conversationId = body.conversation_id;
const contactId = body.contact_id;
const nombreContacto = body.nombre || '';
const empresaId = body.empresa_id;

if (!chatId || !texto) {
  return [{ json: { skip: true, skipReason: 'sin_chat_id_o_texto' } }];
}

// Deduplicación — G54 no manda un ID único de mensaje en el relevo, se arma con chat+conversación+texto+ventana de tiempo
if (!staticData.seenTgMessageIds) staticData.seenTgMessageIds = {};
const now = Date.now();
Object.keys(staticData.seenTgMessageIds).forEach(id => {
  if (now - staticData.seenTgMessageIds[id] > 60000) delete staticData.seenTgMessageIds[id];
});
const dedupeKey = `${chatId}_${conversationId}_${texto}`;
if (staticData.seenTgMessageIds[dedupeKey]) {
  return [{ json: { skip: true, skipReason: 'duplicate_message' } }];
}
staticData.seenTgMessageIds[dedupeKey] = now;

return [{
  json: {
    telefono: 'tg_' + chatId,
    chatId,
    texto,
    nombreContacto,
    conversationId,
    contactId,
    empresaId,
    tipoMensaje: 'text',
    skip: false
  }
}];

const board = $('📋 G54: Buscar Deal Existente (CRM Telegram)').item.json;
const telefono = $('📝 Armar Mensaje Final').item.json.telefono || '';

let match = null;
try {
  for (const etapa of Object.keys(board)) {
    const deals = board[etapa] || [];
    const found = deals.find(d => d.telefono === telefono);
    if (found) { match = found; break; }
  }
} catch (e) { /* si el board no cargó, seguimos como si no existiera */ }

let wa_contact_id = null;
try {
  const contactData = $('🔍 Buscar Contact ID (CRM Telegram)').item.json.data || [];
  wa_contact_id = contactData[0]?.id || null;
} catch (e) { /* si falló el lookup, seguimos sin el vínculo */ }

return [{ json: {
  existe: !!match,
  deal_id: match ? match.id : null,
  telefono,
  wa_contact_id,
}}];

const dealResp = $json;
const dealId = dealResp && dealResp.id ? dealResp.id : null;

let contenido = null;
try {
  const armado = $('📝 Armar Mensaje Final').item.json;
  const clasificacion = armado.clasificacion || '';
  if (clasificacion === 'Caliente') {
    contenido = 'Marco (Telegram): cliente aceptó cotización, clasificado como lead caliente.';
  } else if (clasificacion === 'Consulta') {
    contenido = 'Marco (Telegram): consulta escalada a un especialista.';
  }
} catch (e) { /* si no se puede leer, no se loggea nada */ }

return [{ json: { dealId, contenido, deberiaLoggear: !!(dealId && contenido) } }];

